import { Database } from "bun:sqlite";
import { drizzle } from "drizzle-orm/bun-sqlite";
import { migrate } from "drizzle-orm/bun-sqlite/migrator";
import { join } from "path";

// SQL migrations generated by drizzle-kit (`bun run db:generate:session`), shipped next to src/
// (mirrors apps/core/src/infrastructure/db/app-db.ts's own pattern).
const MIGRATIONS_FOLDER = join(import.meta.dir, "../../../drizzle/session");

// session.db — session-service's own database (services/accounts/proxies/cookies/account_jobs,
// schema: ./schema/session.ts). Separate from core's app.db — core never migrates this file, and
// session-service never migrates app.db (it only reads/requeues core's queue through
// QueueSignalPort, see domain/queue-signal.ts).
export function openSessionDb(dataDir: string): Database {
  const db = new Database(join(dataDir, "session.db"), { create: true });
  db.exec("PRAGMA journal_mode = WAL;");
  migrate(drizzle(db), { migrationsFolder: MIGRATIONS_FOLDER });
  return db;
}
